package com.nth.desktop3d;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.concurrent.atomic.AtomicReference;
/** Focused native checks for creator lighting/alpha, themed menus, dock widgets and full backups. */
public final class ScenesDock079Smoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;
    public ScenesDock079Smoke(Instrumentation t,MainActivity a,String o){test=t;activity=a;output=o;}
    public void run()throws Exception {
        SettingsModel model=(SettingsModel)invokeValue("settingsModel");LauncherStore store=model.store;JSONObject before=DesktopBackup.capture(activity,model);LayeredScene.Document previousDraft=LayeredScene.read(activity,true);int material=model.crystal.material();
        try{
            invoke("closePanel",new Class[]{});LayeredScene.write(activity,null,true);LayeredScene.Document scene=new LayeredScene.Document();LayeredScene.ObjectLayer object=new LayeredScene.ObjectLayer();object.kind="orb";scene.objects.add(object);scene.caustics=.8f;scene.lightSpeed=.7f;LayeredScene.write(activity,scene,false);
            invoke("showModes",new Class[]{});click("Edit my scene");await(()->field("sceneComposer")!=null,"Saved scene did not open for editing");main(()->editor().focus("opacity"));
            main(()->{View v=find("Object transparency");check(v instanceof SeekBar,"Object transparency missing");Bundle args=new Bundle();args.putFloat("android.view.accessibility.action.ARGUMENT_PROGRESS_VALUE",60);check(v.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),args),"Transparency slider inaccessible");check(Math.abs(editor().document.objects.get(0).opacity-.4f)<.01,"Transparency slider did not update object alpha");editor().focus("caustics");check(find("Caustic lighting") instanceof SeekBar&&find("Caustic speed") instanceof SeekBar,"Creator lighting controls missing");editor().persistNow();});capture("079-creator-caustics");
            click("Apply scene");await(()->field("sceneComposer")==null&&model.value("wallpaper_source")==3,"Edited scene was not applied");LayeredScene.Document saved=LayeredScene.read(activity,false);check(Math.abs(saved.objects.get(0).opacity-.4f)<.01&&saved.caustics==.8f&&saved.lightSpeed==.7f,"Scene alpha or lighting did not persist");
            AtomicReference<Bitmap> first=new AtomicReference<>(),second=new AtomicReference<>();main(()->{LayerSceneView v=(LayerSceneView)field("layeredWallpaper");v.moving(false);v.lighting(true);first.set(render(v));});idle(1200);main(()->second.set(render((LayerSceneView)field("layeredWallpaper"))));check(different(first.get(),second.get())>100,"Custom caustics did not animate without tilt");first.get().recycle();second.get().recycle();
            main(()->{LayerSceneView v=(LayerSceneView)field("layeredWallpaper");v.lighting(false);first.set(render(v));});idle(300);main(()->second.set(render((LayerSceneView)field("layeredWallpaper"))));check(different(first.get(),second.get())==0,"Paused custom caustics still move");first.get().recycle();second.get().recycle();
            LauncherStore.Item folder=new LauncherStore.Item("folder","Dock test folder");folder.children.add(new LauncherStore.Item("builtin:notes","Notes"));folder.children.add(new LauncherStore.Item("builtin:calculator","Calculator"));invoke("putDockItem",new Class[]{int.class,LauncherStore.Item.class},0,folder);invoke("putDockItem",new Class[]{int.class,LauncherStore.Item.class},1,new LauncherStore.Item("builtin:settings","Settings"));
            LauncherStore restored=new LauncherStore(activity);check(restored.dock.slots.get(0).item.children.size()==2&&!restored.dock.slots.get(0).item.id.equals(folder.id)&&!restored.dock.slots.get(0).item.children.get(0).id.equals(folder.children.get(0).id),"Dock folder contents/independent identities were lost");
            shell("appwidget grantbind --package com.nth.desktop3d --user 0");AtomicReference<AppWidgetProviderInfo> provider=new AtomicReference<>();main(()->{for(AppWidgetProviderInfo info:AppWidgetManager.getInstance(activity).getInstalledProviders())if(info.provider.getClassName().endsWith(".FixtureWidgetProvider"))provider.set(info);});check(provider.get()!=null,"Widget fixture missing");invoke("chooseWidget",new Class[]{AppWidgetProviderInfo.class,JSONObject.class,int.class},provider.get(),null,2);await(()->store.dock.slots.get(2).widgetId>=0,"Dock widget binding did not finish");
            int id=store.dock.slots.get(2).widgetId;main(()->{((DesktopView)field("desktop")).rebuild();((DockView)field("dockContents")).rebuild();});idle(600);main(()->check(findWidget((View)field("dockContents"),id)!=null,"Dock widget host was cleared by desktop rebuild"));capture("079-dock-app-folder-widget");
            JSONObject archive=DesktopBackup.capture(activity,model);check(archive.getJSONArray("dock").getJSONObject(0).getJSONObject("item").getJSONArray("children").length()==2,"Backup omitted dock folders");check(archive.getJSONArray("widgets").length()>0,"Backup omitted dock widget");JSONObject foreign=new JSONObject(archive.toString()).put("install","another-install");main(()->{try{model.importDesktopBackup(activity,new DesktopBackup.Prepared(foreign,model));}catch(Exception e){throw new AssertionError(e);}});check(store.dock.slots.get(0).item.children.size()==2&&store.dock.slots.get(2).widgetId==-1,"Reinstall restore lost dock contents or reused foreign widget ID");JSONArray queue=new JSONArray(store.preferences.getString("restore_widgets","[]"));JSONObject dockRecord=null;for(int i=0;i<queue.length();i++)if(queue.getJSONObject(i).optString("location").equals("dock"))dockRecord=queue.getJSONObject(i);check(dockRecord!=null&&dockRecord.getInt("slot")==2,"Dock widget lost its restore destination");invoke("restoreWidget",new Class[]{JSONObject.class},dockRecord);await(()->store.dock.slots.get(2).widgetId>=0,"Dock widget could not restore into its original space");
            for(int m=0;m<4;m++){final int choice=m;main(()->{model.crystal.setMaterial(choice);AlertDialog menu=new AreaSettingsMenu(activity,model,"dock",new AreaSettingsMenu.Host(){public void page(String p){}public void setting(String id){}public void setup(){}}).show();check(menu.getWindow().getDecorView().getBackground()!=null,"Themed menu has no material");check(findIn(menu.getWindow().getDecorView(),"Dock spaces count")!=null&&findIn(menu.getWindow().getDecorView(),"Manage dock spaces")!=null,"Dock three-dot menu omitted new controls");menu.dismiss();});}
            invoke("showModes",new Class[]{});click("Remove my scene");systemClick("Cancel");check(LayeredScene.file(activity,false).exists(),"Cancel removed saved scene");click("Remove my scene");systemClick("Remove");await(()->!LayeredScene.file(activity,false).exists()&&model.value("wallpaper_source")==0,"Remove did not clear custom scene and select built-in wallpaper");
        }finally{main(()->{try{invokeDirect("closePanel",new Class[]{});model.importDesktopBackup(activity,new DesktopBackup.Prepared(before,model));model.crystal.setMaterial(material);}catch(Exception e){throw new AssertionError(e);}});LayeredScene.write(activity,previousDraft,true);}
    }
    private Bitmap render(View v){Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));return b;}
    private int different(Bitmap a,Bitmap b){int n=0;for(int y=0;y<a.getHeight();y+=3)for(int x=0;x<a.getWidth();x+=3)if(a.getPixel(x,y)!=b.getPixel(x,y))n++;return n;}
    private View findWidget(View v,int id){if(v instanceof LauncherWidgetView&&((LauncherWidgetView)v).getAppWidgetId()==id)return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=findWidget(((ViewGroup)v).getChildAt(i),id);if(f!=null)return f;}return null;}
    private View findIn(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&((TextView)v).getText().toString().startsWith(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=findIn(((ViewGroup)v).getChildAt(i),text);if(f!=null)return f;}return null;}
    private void systemClick(String text){boolean clicked=false;for(android.view.accessibility.AccessibilityNodeInfo node:test.getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText(text))if(text.contentEquals(node.getText())){clicked=node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);break;}check(clicked,"Dialog action missing: "+text);idle(350);}
    private void shell(String cmd)throws Exception{try(ParcelFileDescriptor pfd=test.getUiAutomation().executeShellCommand(cmd);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(pfd)){while(in.read()!=-1){}}}
    private SceneComposer editor(){return (SceneComposer)field("sceneComposer");}
    private void writePicture(File file,boolean alpha)throws Exception {Bitmap b=Bitmap.createBitmap(96,160,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(alpha?Color.TRANSPARENT:0xFF123B58);Paint p=new Paint(3);p.setColor(alpha?0xFF8AF4DE:0xFF3A7493);c.drawCircle(48,80,30,p);try(FileOutputStream out=new FileOutputStream(file)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    private Object field(String name){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new AssertionError(e);}}
    private Object invokeValue(String name){AtomicReference<Object> r=new AtomicReference<>();main(()->r.set(invokeDirect(name,new Class[]{})));return r.get();}
    private Object invokeDirect(String name,Class<?>[] types,Object...args){try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}}
    private void invoke(String name,Class<?>[] types,Object...args){main(()->invokeDirect(name,types,args));idle(250);}
    private View find(String text){return find(activity.getWindow().getDecorView(),text);}
    private View find(View v,String text){if(v.getVisibility()!=View.VISIBLE)return null;if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View f=find(g.getChildAt(i),text);if(f!=null)return f;}}return null;}
    private void click(String value){main(()->{View v=find(value);check(v!=null,"Missing control: "+value);v.performClick();});idle(250);}
    private void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{r.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void idle(long ms){SystemClock.sleep(ms);test.runOnMainSync(()->{});}
    private void await(java.util.function.BooleanSupplier ready,String message){long until=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<until){AtomicReference<Boolean> r=new AtomicReference<>(false);main(()->r.set(ready.getAsBoolean()));if(r.get())return;idle(100);}throw new AssertionError(message);}
    private void capture(String name){idle(600);Bitmap b=test.getUiAutomation().takeScreenshot();File dir=output==null?new File(activity.getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{b.recycle();}}
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
}
